      SUBROUTINE EDITC---- INSERT OR REMOVE ELEMENT OR ELEMENTS INTO OR FROM DATAC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ICOPY.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LABELI.CIN'      INCLUDE 'LBDAT.CIN'      INCLUDE 'LIMITS.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'C-----------------------------------------------------------------------CC---- COMMA?C      IF (LBDAT .NE. BLANK) THEN        LABELI = LBDAT        GO TO 100      ENDIF      CALL RDNEXT      IF (ENDFIL) GO TO 600      IF (ITEM .EQ. COMMA) THEN        CALL RDNEXT        IF (ENDFIL) GO TO 600      ENDIF      IF (ITEM .EQ. QUOTE .OR. ITEM .EQ. APOST) THEN        IF (LABLE .NE. BLANK) GO TO 100        CALL RDSTRG (LABELI, 15, L)        IF (L .GT. 15) WRITE (NOUT, 9350)      ENDIFC  100 CALL EXILEC      ISTOR(1) = 1      NUM = NELLIM - NEL + 1      NDIF = 1      NEL = 0      I = 1      I100 = 0      IB100 = ISTOR(NUM)      CALL FND100C      CALL INDUCTC  500 CALL RDNEXT      IF (ENDFIL) GO TO 600      IF (ITEM .EQ. SEMI) THEN        NINSRT = 0      ELSE        NINSRT = 1        CALL RDBACK      ENDIFC  600 CONTINUE      RETURN 9350 FORMAT ('0NEXT LABEL TRUNCATED TO 15 CHARS.') 9360 FORMAT (8H0LABEL ",A8,33H" ON NEXT ELEMENT WAS OVERWRITTEN)      END